(function(root){
'use strict';
const M=root.DistilleryMath;
function words(lang){return {t:(pl,en)=>lang==='pl'?pl:en,n:(v,d=3)=>new Intl.NumberFormat(lang==='pl'?'pl-PL':'en-GB',{maximumFractionDigits:d}).format(v)};}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=s=>'<p>'+s+'</p>',eq=s=>'<div class="worked-equation">'+s+'</div>';
function steps(items){return '<ol class="worked-steps">'+items.map(([title,body])=>'<li><h4>'+title+'</h4>'+body+'</li>').join('')+'</ol>';}
function slider(label,min,max,step,value){return '<div class="lab-field"><label for="model-lab-slider">'+label+'</label><input id="model-lab-slider" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+value+'"></div><div id="model-lab-result" aria-live="polite" aria-atomic="true"></div>';}
function lab(key,lang,D,P){
 const {t,n}=words(lang),h=M.huberThreshold(P);
 let title,body;
 if(key==='ridge'){
  title=t('Jak dodatek za wielkość mnożników trafia do równania?','How does the multiplier-size addition enter the equation?');
  body=p(t('W ćwiczeniu z oczekiwaniami A i B oba przepisy idealnie odtwarzały trzy zapisane pomiary. Ich błąd dopasowania wynosił zero. Różniła je wrażliwość na rozchodzenie się A i B. Teraz zobacz, jak reguła Ridge ocenia te dwa przepisy.','In the A/B wait exercise both recipes exactly reproduced the three recorded observations. Their fitting error was zero. What differed was their sensitivity when A and B moved apart. Now see how the Ridge rule scores these two recipes.'))+
   steps([[t('Policz błąd na zapisanych pomiarach','Calculate error on recorded observations'),eq(t('średnia kwadratów (pomiar − prognoza) / 2','mean of squared (observation − prediction) / 2'))+p(t('Kwadraty sprawiają, że chybienie w górę i w dół się nie kasują. W obu naszych kandydatach ten składnik wynosi 0.','Squares prevent misses in opposite directions from cancelling. This term is 0 for both our candidates.'))],
   [t('Policz wielkość mnożników','Calculate the size of the multipliers'),eq('10² + (−9)² = 181')+eq(t('0,5² + 0,5² = 0,5','0.5² + 0.5² = 0.5'))+p(t('Duże przeciwstawne mnożniki dostają większy dodatek. To świadoma preferencja mniejszej wrażliwości, gdy podobny wynik można uzyskać spokojniejszym przepisem.','Large opposing multipliers receive a larger addition. This deliberately favours lower sensitivity when a calmer recipe can fit similarly well.'))],
   [t('Połącz obie oceny','Combine the two scores'),eq(t('ocena = błąd dopasowania + λ × suma kwadratów mnożników / 2','score = fitting error + λ × sum of squared multipliers / 2'))+p(t('Mniej punktów = lepiej: model szuka najmniejszej łącznej oceny. λ (lambda) określa siłę dodatku. Porównujemy kandydatów przy tej samej λ. Dzielenie przez 2 upraszcza późniejsze równania.','Fewer points = better: the model seeks the lowest total score. λ (lambda) sets the strength of the addition. Compare candidates at the same λ. Dividing by 2 simplifies later equations.'))]])+
   slider(t('Siła preferencji λ — tylko porównanie tych dwóch kandydatów','Preference strength λ — compare only these two candidates'),0,1,.05,.1)+
   p(t('Przy λ = 0 jest remis. Przy λ > 0 z tej pary model preferuje drugi przepis, bo ma on mniej punktów. Pełny Ridge dobiera wszystkie mnożniki i znajdzie jeszcze niższą ocenę: trochę mniejsze mnożniki za cenę małego błędu dopasowania. Ten suwak nie szuka tego minimum ani najlepszej λ.','At λ = 0 there is a tie. For λ > 0 the model prefers the second of these two recipes because it scores fewer points. Full Ridge adjusts all multipliers and will find an even lower score: slightly smaller multipliers in exchange for a small fitting error. This slider neither finds that optimum nor selects the best λ.'))+
   p(t('Zmiana λ zmienia regułę oceny kandydatów. Sumy przy różnych λ nie służą do wyboru najlepszej λ: wyzerowanie dodatku samo obniża ocenę. Użyteczność ustawienia sprawdzamy przez błędy prognoz na późniejszych oknach, których model nie używał do nauki.','Changing λ changes the scoring rule for candidates. Totals at different λ values do not select the best λ: removing the penalty itself lowers the score. Test a setting’s usefulness through prediction errors on later windows the model did not learn from.'))+
   p(t('W pełnym rachunku z naszych danych jest 1 338 par i cztery mnożniki. Sumujemy kwadraty wszystkich błędów, dzielimy przez 2 × 1 338 i dodajemy λ × sumę kwadratów czterech mnożników / 2. Układ równań i eliminacja Gaussa w rozdziale „Sygnał” wyznaczają minimum tej oceny dla wybranej λ.','The full calculation on our data has 1,338 pairs and four multipliers. Sum all squared errors, divide by 2 × 1,338 and add λ × the sum of the four squared multipliers / 2. The equations and Gaussian elimination in “Signal” find the minimum of this score for the selected λ.'));
 }else if(key==='elastic'){
  title=t('Kiedy dodatkowy mnożnik pozostaje na zerze?','When does the extra multiplier stay at zero?');
  body=p(t('Wracamy do prognozy +10 AAS i pomiaru +10,6 AAS. Dodatkowe oczekiwanie ma przeskalowaną zmianę równą 1, więc jego mnożnik β dopisuje 1 × β. Nowa prognoza to 10 + β, a pomyłka to 10,6 − (10 + β) = 0,6 − β.','Return to the +10 AAS prediction and +10.6 AAS observation. The extra wait has a scaled change of 1, so its multiplier β adds 1 × β. The new prediction is 10 + β and the error is 10.6 − (10 + β) = 0.6 − β.'))+
   steps([[t('Zapisz ocenę kandydata','Write the candidate score'),eq(t('ocena = (0,6 − β)² / 2 + λ × 0,2 × |β| + λ × 0,8 × β² / 2','score = (0.6 − β)² / 2 + λ × 0.2 × |β| + λ × 0.8 × β² / 2'))+p(t('Pierwszy składnik ocenia pomyłkę. Drugi (L1) rośnie proporcjonalnie do wielkości mnożnika bez znaku. Trzeci (L2) rośnie z jego kwadratem. α = 0,2 oznacza, że przy L1 stoi 0,2 × λ, a przy L2 pozostałe 0,8 × λ. Mniej punktów = lepiej. Dzielenie kwadratów przez 2 to przyjęta konwencja rachunku: upraszcza regułę aktualizacji, w której próg L1 wynosi λ × α.','The first term scores the miss. The second (L1) grows in proportion to the multiplier’s unsigned size. The third (L2) grows with its square. α = 0.2 puts 0.2 × λ in front of L1 and the remaining 0.8 × λ in front of L2. Fewer points = better. Dividing the squared terms by 2 is the chosen convention: it simplifies the update rule so that the L1 threshold is λ × α.'))],
   [t('Podstaw λ = 4 i porównaj dwa mnożniki','Set λ = 4 and compare two multipliers'),
   p(t('Wtedy waga L1 wynosi 4 × 0,2 = 0,8, a waga kwadratu to 4 × 0,8 / 2 = 1,6. W tabeli rozpisujemy każdy składnik. Model preferuje niższą sumę punktów.','The L1 weight is then 4 × 0.2 = 0.8, and the square is weighted by 4 × 0.8 / 2 = 1.6. The table expands each term. The model prefers the lower total score.'))+
   '<div class="table-wrap"><table class="intuition-table en-arithmetic"><caption>'+t('Dwa warianty przy λ = 4, α = 0,2','Two candidates at λ = 4, α = 0.2')+'</caption><thead><tr><th>'+t('Co liczymy?','Calculation')+'</th><th>β = 0</th><th>'+t('β = 0,1','β = 0.1')+'</th></tr></thead><tbody>'+
   '<tr><th>'+t('Prognoza (AAS)','Prediction (AAS)')+'</th><td>10 + 0 = 10</td><td>'+t('10 + 0,1 = 10,1','10 + 0.1 = 10.1')+'</td></tr>'+
   '<tr><th>'+t('Pomyłka (AAS)','Error (AAS)')+'</th><td>'+t('10,6 − 10 = 0,6','10.6 − 10 = 0.6')+'</td><td>'+t('10,6 − 10,1 = 0,5','10.6 − 10.1 = 0.5')+'</td></tr>'+
   '<tr><th>'+t('Punkty za pomyłkę','Error score')+'</th><td>'+t('0,6² / 2 = 0,18','0.6² / 2 = 0.18')+'</td><td>'+t('0,5² / 2 = 0,125','0.5² / 2 = 0.125')+'</td></tr>'+
   '<tr><th>L1</th><td>'+t('0,8 × 0 = 0','0.8 × 0 = 0')+'</td><td>'+t('0,8 × 0,1 = 0,08','0.8 × 0.1 = 0.08')+'</td></tr>'+
   '<tr><th>L2</th><td>'+t('1,6 × 0² = 0','1.6 × 0² = 0')+'</td><td>'+t('1,6 × 0,1² = 0,016','1.6 × 0.1² = 0.016')+'</td></tr>'+
   '<tr><th>'+t('Łączna ocena','Total score')+'</th><td>'+t('0,18 + 0 + 0 = 0,18','0.18 + 0 + 0 = 0.18')+'</td><td>'+t('0,125 + 0,08 + 0,016 = 0,221','0.125 + 0.08 + 0.016 = 0.221')+'</td></tr></tbody></table></div>'],
   [t('Oddziel poprawę prognozy od zmiany punktów','Separate prediction improvement from score changes'),
   p(t('Mnożnik 0,1 zmniejsza pomyłkę z 0,6 do 0,5 AAS: poprawa wynosi 0,1 AAS. Ocena tej pomyłki zmienia się inaczej, bo liczymy kwadrat podzielony przez 2:','Multiplier 0.1 reduces the miss from 0.6 to 0.5 AAS: an improvement of 0.1 AAS. Its score changes differently because we square it and divide by 2:'))+
   eq(t('Ubywa punktów za pomyłkę: 0,18 − 0,125 = 0,055','Error points saved: 0.18 − 0.125 = 0.055'))+
   eq(t('Przybywa za L1 i L2: (0,08 + 0,016) − 0 = 0,096','L1 and L2 points added: (0.08 + 0.016) − 0 = 0.096'))+
   eq(t('Bilans: +0,096 − 0,055 = +0,041','Net change: +0.096 − 0.055 = +0.041'))+
   eq(t('Sprawdzenie: 0,221 − 0,18 = +0,041','Check: 0.221 − 0.18 = +0.041'))+
   p(t('Prognoza jest bliżej pomiaru, ale suma punktów rośnie. Przy λ = 4 model preferuje więc β = 0, pozostawiając pomyłkę 0,6 AAS. To działanie wybranej reguły upraszczania; jej przydatność sprawdzamy na kolejnych oknach.','The prediction is closer to the observation, but the total score increases. At λ = 4 the model therefore prefers β = 0, leaving a 0.6 AAS miss. This is the chosen simplification rule at work; later windows test its usefulness.'))],
   [t('Sprawdź każdy dodatni mnożnik, także bardzo mały','Check every positive multiplier, including tiny ones'),
   p(t('Zamiast próbować kolejno 0,1, 0,01 i 0,001, przekształćmy wzór. Dla dodatniego β wartość |β| jest równa β. Przy λ = 4 otrzymujemy:','Instead of trying 0.1, 0.01 and 0.001 one by one, rearrange the formula. For positive β, |β| equals β. With λ = 4:'))+
   eq(t('ocena = (0,6 − β)² / 2 + 0,8β + 1,6β²','score = (0.6 − β)² / 2 + 0.8β + 1.6β²'))+
   p(t('Rozwiń kwadrat, mnożąc (0,6 − β) przez (0,6 − β):','Expand the square by multiplying (0.6 − β) by (0.6 − β):'))+
   eq(t('(0,6 − β)² = 0,36 − 1,2β + β²','(0.6 − β)² = 0.36 − 1.2β + β²'))+
   eq(t('(0,6 − β)² / 2 = 0,18 − 0,6β + 0,5β²','(0.6 − β)² / 2 = 0.18 − 0.6β + 0.5β²'))+
   p(t('Zbierz osobno wyrazy z β i z β²:','Collect the terms in β and in β² separately:'))+
   eq(t('ocena = 0,18 + (0,8 − 0,6)β + (0,5 + 1,6)β²','score = 0.18 + (0.8 − 0.6)β + (0.5 + 1.6)β²'))+
   eq(t('ocena = 0,18 + 0,2β + 2,1β²','score = 0.18 + 0.2β + 2.1β²'))+
   p(t('Tutaj 0,2 powstało z 0,8 − 0,6, a 2,1 z 0,5 + 1,6. Ta wartość 0,2 wynika z bilansu zysku i dodatku przy λ = 4; tylko przypadkiem jest równa ustawieniu α. Przy β = 0 zostaje 0,18. Każdy dodatni β dopisuje dwie dodatnie liczby, więc zwiększa ocenę. Na przykład β = 0,1 dodaje 0,2 × 0,1 + 2,1 × 0,1² = 0,02 + 0,021 = 0,041 — tak jak w tabeli.','Here 0.2 comes from 0.8 − 0.6, and 2.1 from 0.5 + 1.6. This 0.2 comes from the balance of improvement and penalty at λ = 4; it only happens to equal the setting α. At β = 0 the score is 0.18. Every positive β adds two positive numbers, increasing the score. For example, β = 0.1 adds 0.2 × 0.1 + 2.1 × 0.1² = 0.02 + 0.021 = 0.041, matching the table.'))+
   p(t('Ujemny β obniża prognozę poniżej 10, oddalając ją od pomiaru 10,6, i również dodaje punkty L1 oraz L2. Żaden dodatni ani ujemny mnożnik nie wygrywa więc z zerem.','A negative β lowers the prediction below 10, further from the observation of 10.6, and also adds L1 and L2 points. Neither a positive nor a negative multiplier therefore beats zero.'))]])+
   slider(t('Zmień λ: który mnożnik daje najmniej punktów?','Change λ: which multiplier scores the fewest points?'),0,4,.05,0)+
   p(t('Porównuj kolumny przy jednej λ: wygrywa najmniejsza suma. Przy λ = 0 nasz przykład osiąga 0 punktów, a przy λ = 4 — 0,18. Czy to dowód, że λ = 0 jest lepsza? Nie: przy zerowej λ po prostu nie naliczamy dodatków. Aby wybrać λ, porównujemy zamiast tego błędy prognoz na późniejszych oknach, bez dodatków L1 i L2.','Compare columns at one λ: the smallest total wins. At λ = 0 our example reaches 0 points, while at λ = 4 it reaches 0.18. Does that prove λ = 0 is better? No: at zero λ we simply charge no penalties. To choose λ, compare prediction errors on later windows instead, without L1 and L2 additions.'))+
   '<details><summary>'+t('Skąd wzór suwaka, dla dowolnej λ?','Where does the slider formula come from, for any λ?')+'</summary>'+
   p(t('Rozwiń kwadrat tak samo jak przy λ = 4. Dla dodatniego β otrzymujemy:','Expand the square as we did at λ = 4. For positive β we obtain:'))+
   eq(t('ocena = 0,18 − (0,6 − 0,2λ)β + (1 + 0,8λ)β² / 2','score = 0.18 − (0.6 − 0.2λ)β + (1 + 0.8λ)β² / 2'))+
   p(t('Liczba 1 w nawiasie pochodzi z kwadratu pomyłki, a 0,8λ z dodatku L2. Gdy λ ≥ 3, wyrażenie 0,6 − 0,2λ jest niedodatnie. Wtedy oba składniki zawierające dodatni β podnoszą ocenę względem zera.','The 1 in the bracket comes from squared error and 0.8λ from L2. When λ ≥ 3, the expression 0.6 − 0.2λ is non-positive. Both terms containing positive β then increase the score above its value at zero.'))+
   p(t('Dla λ < 3 można przestawić ten sam rachunek w kwadrat odległości od jednej liczby:','For λ < 3, rearrange the same calculation as a squared distance from one number:'))+
   eq(t('ocena = (1 + 0,8λ) / 2 × [β − (0,6 − 0,2λ) / (1 + 0,8λ)]² + C','score = (1 + 0.8λ) / 2 × [β − (0.6 − 0.2λ) / (1 + 0.8λ)]² + C'))+
   eq(t('C = 0,18 − (0,6 − 0,2λ)² / [2 × (1 + 0,8λ)]','C = 0.18 − (0.6 − 0.2λ)² / [2 × (1 + 0.8λ)]'))+
   p(t('C nie zależy od β, więc wybieramy β zerujące kwadrat. Stąd iloraz w suwaku. Gdy licznik jest niedodatni, dodatni ruch nie pomaga, a ujemny oddala prognozę od 10,6 — wybieramy zero. Zapis max(…; 0) wybiera większą z dwóch liczb i łączy obie sytuacje w jednym wzorze.','C does not depend on β, so choose β to make the square zero. That gives the slider’s ratio. When the numerator is non-positive, positive movement cannot help and negative movement takes the prediction further from 10.6: choose zero. The max(…, 0) notation chooses the larger of the two numbers, combining both cases in one formula.'))+'</details>'+
   eq(t('β = max(0,6 − 0,2 × λ; 0) / (1 + 0,8 × λ)','β = max(0.6 − 0.2 × λ, 0) / (1 + 0.8 × λ)'))+
   p(t('Od stałej różnicy 0,6 odejmujemy próg 0,2 × λ. Jeśli nic dodatniego nie zostanie, wpisujemy zero. Pozostałą część dzielimy przez 1 + 0,8 × λ. Stąd granica: 0,2 × 3 = 0,6. Dla λ ≥ 3 licznik wynosi dokładnie zero.','Subtract threshold 0.2 × λ from the fixed difference of 0.6. If nothing positive remains, use zero. Divide what remains by 1 + 0.8 × λ. This gives the boundary: 0.2 × 3 = 0.6. For λ ≥ 3 the numerator is exactly zero.'))+
   '<h4>'+t('Jak ten krok wygląda dla wszystkich pomiarów?','How does this step work over all observations?')+'</h4>'+
   p(t('JAS-MIN bierze jedno oczekiwanie, chwilowo zostawiając pozostałe mnożniki bez zmian. Dla każdej pary sąsiednich okien mnoży przeskalowaną zmianę tego oczekiwania przez różnicę, której nie wyjaśniają pozostałe. Średnia tych iloczynów jest sygnałem do aktualizacji: nazwijmy ją c. To już nie sama różnica 0,6 z naszej miniatury.','JAS-MIN takes one wait, holding the other multipliers fixed for the moment. For each pair of adjacent windows, it multiplies that wait’s scaled change by the difference not explained by the others. The mean of those products is the update signal: call it c. This is no longer just the 0.6 difference from our miniature.'))+
   p(t('Gdy |c| ≤ λ × α, kod przypisuje β = 0. Poza tym zakresem zachowuje znak c, odejmuje próg od |c| i dzieli przez średnią kwadratów wejścia + λ × (1 − α). To soft thresholding. Następnie aktualizuje różnice i przechodzi do kolejnego oczekiwania. Powtarza obieg, aż zmiany mnożników będą wystarczająco małe albo osiągnie limit iteracji. λ i α podczas tych obiegów się nie zmieniają; wyzerowany mnożnik może jeszcze wrócić, jeśli zmienią się pozostałe.','When |c| ≤ λ × α, the code assigns β = 0. Outside that range, it keeps the sign of c, subtracts the threshold from |c| and divides by the mean squared input + λ × (1 − α). This is soft thresholding. It then updates the differences and moves to the next wait. It repeats until multiplier changes are small enough or the iteration limit is reached. λ and α stay fixed through these passes; a zeroed multiplier can become active again as the others change.'));
 }else if(key==='huber'){
  title=t('Próg z prawdziwych danych i reakcja na błąd','The real-data threshold and response to error');
  body=p(t('„Nacisk” to tempo przyrostu punktów, gdy wielkość pomyłki rośnie, przeliczone na 1 AAS. Dla zwykłego kwadratu / 2 pomyłka 2 daje 2 punkty, a 2,01 daje 2,02005. Przyrost 0,02005 podzielony przez mały krok 0,01 wynosi 2,005. Przy coraz mniejszym kroku zbliża się do 2, czyli wielkości błędu. Powyżej progu Hubera tempo wynosi już stale δ.','“Pressure” means the rate at which points increase as the error magnitude grows, per 1 AAS. With ordinary square / 2, error 2 scores 2 and error 2.01 scores 2.02005. The increase 0.02005 divided by the small step 0.01 is 2.005. As the step gets smaller this approaches 2, the error size. Above the Huber threshold, the rate is constant at δ.'))+'<h4>'+t('Skąd w scence wzięło się 10,75 AAS?','Where did the miniature’s 10.75 AAS come from?')+'</h4>'+p(t('Dla początkowego progu δ = 3 w ćwiczeniu wyżej mały błąd daje nacisk równy swojej wielkości, a duży — najwyżej 3. Przy prognozie 10,75 cztery pomiary równe 10 ciągną prognozę w dół po 0,75. Razem: 4 × 0,75 = 3. Pomiar równy 30 ciągnie ją w górę, ale jego nacisk zatrzymuje się na 3. Te działania się równoważą.','At the initial threshold δ = 3 in the exercise above, a small error exerts pressure equal to its magnitude; a large error exerts at most 3. At a prediction of 10.75, each of the four observations of 10 pulls down by 0.75. Together: 4 × 0.75 = 3. The observation of 30 pulls up, but its pressure stops at 3. These effects balance.'))+eq(t('4 × (prognoza − 10) = 3 → prognoza = 10 + 3 / 4 = 10,75','4 × (prediction − 10) = 3 → prediction = 10 + 3 / 4 = 10.75'))+p(t('„Nacisk” opisuje, jak zmienia się ocena błędów, kiedy przesuwamy prognozę. Tutaj równowaga wyznacza minimum tej oceny. Piąty pomiar jest oddalony od prognozy o 30 − 10,75 = 19,25 AAS.','“Pressure” describes how the error score changes when we move the prediction. Here the balance determines the minimum score. The fifth observation is 30 − 10.75 = 19.25 AAS away from the prediction.'))+
   p(t('Próg 3 AAS w scence pięciu sytuacji wybraliśmy do pokazu. Nie wyliczaliśmy go regułą poniżej: cztery identyczne zmiany dałyby MAD = 0 i próg równy dolnemu ograniczeniu 0,000001. Teraz przechodzimy do innego zbioru — naszych 1 338 rzeczywistych zmian.','The 3 AAS threshold in the five-situation miniature was chosen for illustration. We did not calculate it with the rule below: four identical changes would give MAD = 0 and a threshold at the 0.000001 floor. Now we move to a different dataset: our 1,338 authentic changes.'))+steps([[t('Zacznij od zmian obciążenia, przed dopasowaniem','Start with load changes, before fitting'),p(t('Mamy 1 338 wartości Δ AAS. Porządkujemy ich kopię od najmniejszej do największej. Mediana to środek: przy parzystej liczbie wpisów średnia dwóch środkowych. Wpisy nr 669 i 670 po zaokrągleniu mają po −0,4 AAS, więc ich średnia wynosi ','We have 1,338 Δ AAS values. Sort a copy from smallest to largest. The median is the middle: with an even count, the average of the two middle entries. Entries 669 and 670 both round to −0.4 AAS, so their mean is ')+n(h.median)+' AAS. '+t('To punkt odniesienia do oceny rozrzutu zmian.','This is our reference point for measuring the spread of changes.'))],
   [t('Policz odległości od tego środka i wybierz środkową','Calculate distances from the centre and take their median'),eq(t('odległość = |Δ AAS − (−0,4)|','distance = |Δ AAS − (−0.4)|'))+p(t('Np. zmiana +78,8 AAS jest odległa o 79,2 od środka −0,4. Liczymy wszystkie 1 338 takich odległości i ustawiamy je od najmniejszej. Środkowe wpisy nr 669 i 670 mają wartość 2,4 AAS na dokładności zapisu danych, więc mediana odległości wynosi ','For example, a +78.8 AAS change is 79.2 away from the centre of −0.4. Calculate all 1,338 distances and sort them from smallest to largest. Middle entries 669 and 670 are both 2.4 AAS at the precision of the recorded data, so the median distance is ')+n(h.mad)+' AAS. '+t('To MAD: mediana bezwzględnych odchyleń. Pojedyncza gigantyczna odległość nie przesuwa środka tak jak średniej.','This is MAD: median absolute deviation. One huge distance cannot pull the middle around the way it can pull a mean.'))],
   [t('Zastosuj regułę zapisaną w algorytmie','Apply the rule in the algorithm'),eq('δ = 1'+(lang==='pl'?',':'.')+'345 × '+n(h.mad)+' = '+n(h.delta)+' AAS')+p(t('Kod JAS-MIN wybiera regułę: 1,345 razy MAD. Z danych pochodzi MAD = 2,4, natomiast mnożnik 1,345 jest wpisany w program — nie został dopasowany do tych pomiarów. Ta reguła ustawia próg o 34,5% powyżej MAD. Dolne ograniczenie 0,000001 zapobiega zerowemu progowi.','JAS-MIN uses the rule 1.345 times MAD. MAD = 2.4 comes from the data, while the multiplier 1.345 is a program constant, not fitted to these observations. This rule sets the threshold 34.5% above MAD. A floor of 0.000001 prevents a zero threshold.'))],
   [t('Dopiero teraz porównuj błędy dopasowanego modelu z progiem','Only now compare fitted-model errors with the threshold'),p(t('Do wyboru progu użyliśmy odległości od mediany. W kolejnych obliczeniach sprawdzamy już coś innego: odległość pomiaru od aktualnego przewidywania Hubera. δ zostaje stałe, ale te błędy i ich wagi mogą się zmieniać.','The threshold came from distances to the median. During fitting we check a different distance: observation minus the current Huber prediction. δ stays fixed, while those errors and their weights can change.'))]])+
   p(t('Obstaw: jeśli błąd wzrośnie z 4 do 8 AAS, czy jego koszt u Hubera będzie cztery razy większy?','Your guess: if the error rises from 4 to 8 AAS, will its Huber cost quadruple?'))+
   slider(t('Wielkość pomyłki |r| w AAS — zobacz jej ocenę przy δ = 3,228','Error magnitude |r| in AAS — see its score at δ = 3.228'),0,12,.001,4)+
   '<div class="lab-presets">'+[[2,'2 AAS'],[4,'4 AAS'],[8,'8 AAS'],[Math.abs(P.dy[D.focus]-(D.models.huber.intercept+M.dot(P.z[D.focus],D.models.huber.beta))),t('Prawdziwa para ','Real pair ')+(D.focus+1)+' → '+(D.focus+2)]].map(([v,label])=>'<button type="button" data-lab-value="'+v+'">'+label+'</button>').join('')+'</div>'+
   p(t('Przy δ = 3,228 pomyłka 4 AAS daje około 7,70 punktu, a 8 AAS — około 20,61. To około 2,7 razy więcej. Dla zwykłego kwadratu / 2 byłoby 8 i 32 punkty, czyli 4 razy więcej.','At δ = 3.228, an error of 4 AAS scores about 7.70 and an error of 8 AAS about 20.61. That is about 2.7 times more. Ordinary squared error / 2 would give 8 and 32 points: 4 times more.'))+
   p(t('Podczas dopasowania punkt dostaje wagę 1, gdy |r| ≤ δ, lub δ / |r| powyżej progu. Mniejsza waga osłabia wpływ tego błędu w następnym kroku dopasowania: np. błąd 8 przy progu 3,228 ma wagę 3,228 / 8 = 0,4035, więc jego ważony nacisk wynosi 0,4035 × 8 = 3,228. Wpływ na konkretny współczynnik zależy też od wartości oczekiwania.','During fitting a point gets weight 1 when |r| ≤ δ, or δ / |r| above the threshold. A smaller weight reduces that error’s influence in the next fitting step: for example, error 8 at threshold 3.228 has weight 3.228 / 8 = 0.4035, giving weighted pressure 0.4035 × 8 = 3.228. Influence on a particular coefficient also depends on predictor values.'))+
   eq(t('punkty błędu: r² / 2, gdy |r| ≤ δ; inaczej δ × (|r| − δ / 2)','error score: r² / 2 when |r| ≤ δ; otherwise δ × (|r| − δ / 2)'));
 }else{
  title=t('Jedna wpadka czy cztery małe zapasy?','One shortage or four small surpluses?');
  body=p(t('W pubie: zapasowa beczka zajmuje miejsce. Pusta beczka w środku meczu to kłopot dla całego pubu. Nierówną ocenę obu pomyłek przełóżmy teraz na liczby z pięciu sytuacji w bazie.','At the pub: a spare keg takes up space. An empty keg during the match is trouble for the whole pub. Now put that unequal scoring into numbers for five database situations.'))+
   p(t('Ilustracja: pięć sytuacji o takich samych wartościach oczekiwań. Obciążenie wzrosło o 10, 10, 10, 10 i 30 AAS. Wybieramy dla nich jedno wspólne przewidywanie. To nie wiersze z naszego zbioru.','Illustration: five situations with identical wait values. Load rose by 10, 10, 10, 10 and 30 AAS. We choose one common prediction for them. These are not rows from our dataset.'))+
   steps([[t('Przewiduj 10: trafiasz cztery razy, raz mocno zaniżasz','Predict 10: four hits, one large underestimate'),eq('4 × 0 + 0'+(lang==='pl'?',':'.')+'95 × (30 − 10) = 19')],
   [t('Przewiduj 30: cztery razy zawyżasz, duży wzrost trafiasz','Predict 30: four overestimates, the large rise is covered'),eq('4 × 0'+(lang==='pl'?',':'.')+'05 × (30 − 10) + 0 = 4')+p(t('19 → 4: suma jest mniejsza, choć cztery przewidywania są za wysokie. W tym zadaniu bardziej zależy nam na unikaniu niedoszacowania niż na trafianiu w środek wyników. Średnia tych zmian wynosi 14.','19 → 4: the total is smaller even though four predictions are too high. This objective puts more weight on avoiding underestimation than on hitting the centre of the outcomes. The mean of these five changes is 14.'))]])+
   p(t('Obstaw: czy Q95 zawsze musi wybrać największy wynik? Najpierw sprawdź pięć sytuacji, potem zmień częstość dużego skoku.','Your guess: must Q95 always pick the largest value? First test five situations, then change how often the large jump occurs.'))+
   '<div class="lab-field"><label for="q-frequency">'+t('Eksperyment: jak często przychodzi duży wzrost?','Experiment: how often does the large rise occur?')+'</label><select id="q-frequency"><option value="4">'+t('4 × 10 AAS + 1 × 30 AAS (raz na 5)','4 × 10 AAS + 1 × 30 AAS (1 in 5)')+'</option><option value="19">'+t('19 × 10 AAS + 1 × 30 AAS (raz na 20)','19 × 10 AAS + 1 × 30 AAS (1 in 20)')+'</option><option value="20">'+t('20 × 10 AAS + 1 × 30 AAS (raz na 21)','20 × 10 AAS + 1 × 30 AAS (1 in 21)')+'</option></select></div>'+
   slider(t('Twoje przewidywanie zmiany obciążenia (AAS)','Your predicted load change (AAS)'),0,40,'any',10)+
   '<div class="lab-presets"><button type="button" data-lab-value="10">10 AAS</button><button type="button" data-q-mean>'+t('Średnia dla tej częstości','Mean at this frequency')+'</button><button type="button" data-lab-value="30">30 AAS</button></div>'+
   p(t('W pierwszym wariancie, przesuwając prognozę w górę o 1 AAS pomiędzy 10 a 30, dodajesz 4 × 0,05 = 0,20 punktu za zawyżanie i odejmujesz 0,95 za zaniżanie. Bilans: −0,75, więc opłaca się iść w górę. Powyżej 30 wszystkie przewidywania są już za wysokie i łączny koszt znowu rośnie.','In the first variant, moving the prediction up by 1 AAS between 10 and 30 adds 4 × 0.05 = 0.20 for overestimates and removes 0.95 for the underestimate. Net change: −0.75, so moving up pays. Above 30 every prediction is too high and total cost rises again.'))+
   p(t('Zmień częstość na „raz na 20”. Podniesienie prognozy o 1 AAS między 10 a 30 dodaje za zawyżenia 19 × 0,05 = 0,95 punktu i odejmuje za jedno zaniżenie 0,95. Każda prognoza w tym przedziale daje ten sam wynik. Przy „raz na 21” dodatki wynoszą 20 × 0,05 = 1,00, więcej niż oszczędzane 0,95 — wygrywa prognoza 10. Maksimum nadal wynosi 30, a średnia około 10,95. Q95 może więc wypaść także poniżej średniej, gdy duże wyniki zdarzają się rzadziej niż raz na 20 i podnoszą średnią.','Switch to “1 in 20”. Raising the prediction by 1 AAS between 10 and 30 adds 19 × 0.05 = 0.95 overprediction points and saves 0.95 on one underestimate. Every prediction in that range ties. At “1 in 21”, the added score is 20 × 0.05 = 1.00, exceeding the 0.95 saved: prediction 10 wins. The maximum is still 30 and the mean about 10.95. Q95 can therefore also be below the mean when large outcomes occur less often than 1 in 20 and pull the mean upwards.'))+
   p(t('Pełny Q95 dobiera przewidywanie do wartości oczekiwań i minimalizuje takie koszty ze wszystkich wierszy (z dodatkiem regularyzacji w tej implementacji). Te pięć przykładów tłumaczy kierunek działania, nie dowodzi 95% pokrycia. Suwak nie przelicza naszego niezbieżnego dopasowania Q95.','Full Q95 makes its prediction depend on wait values and minimizes these costs across all rows (with a regularization term in this implementation). These five examples explain the direction of the effect, not 95% coverage. This slider does not refit our non-converged Q95 model.'));
 }
 return '<section class="model-lab" data-lab="'+key+'"><span class="lab-kind">'+t(key==='huber'?'RZECZYWISTY PRÓG + EKSPERYMENT Z BŁĘDEM':'MINI-EKSPERYMENT · LICZBY ILUSTRACYJNE',key==='huber'?'REAL THRESHOLD + ERROR EXPERIMENT':'MINI EXPERIMENT · ILLUSTRATIVE NUMBERS')+'</span>'+p(key==='elastic'?t('Suwak λ w tej sekcji jest połączony z suwakiem w wykresie powyżej.','The λ slider here is linked to the slider in the chart above.'):t('Ta sekcja ma własny suwak do sprawdzania rachunku.','This section has its own slider for checking the arithmetic.'))+'<h3>'+title+'</h3>'+body+'</section>';
}
// Small SVG charts share a fixed viewBox; labels and full arithmetic remain in text.
function chart(curves,{xmax,ymax,xlabel,ylabel,marker,threshold}){
 const x=v=>42+v/xmax*330,y=v=>160-v/ymax*120;
 return '<svg class="lab-chart" viewBox="0 0 400 200" role="img" aria-label="'+esc(ylabel+' / '+xlabel)+'"><path class="lab-axis" d="M42 32 V160 H377"/>'+curves.map(c=>'<path fill="none" stroke="'+c.color+'" stroke-width="2.5" d="'+Array.from({length:101},(_,i)=>{const v=i/100*xmax;return(i?'L':'M')+x(v).toFixed(2)+','+y(c.fn(v)).toFixed(2);}).join('')+'"/>').join('')+(threshold===undefined?'':'<path class="lab-guide" d="M'+x(threshold)+' 32 V160"/><text x="'+x(threshold)+'" y="24" text-anchor="middle">δ</text>')+(marker?'<circle cx="'+x(marker.x)+'" cy="'+y(marker.y)+'" r="5" fill="currentColor"/>':'')+'<text x="30" y="176">0</text><text x="372" y="176" text-anchor="end">'+xmax+'</text><text x="42" y="17">'+esc(ylabel)+'</text><text x="205" y="195" text-anchor="middle">'+esc(xlabel)+'</text></svg>';
}
function result(key,value,lang,D,routineCount=4){
 const {t,n}=words(lang);
 if(key==='ridge'){
  const first=value*181/2,second=value*.5/2;
  return '<div class="lab-readout">λ = '+n(value)+'</div><div class="lab-comparison"><div><h4>10 × A − 9 × B</h4>'+eq('0 + '+n(value)+' × 181 / 2 = '+n(first))+p(t('błąd dopasowania + dodatek','fitting error + addition'))+'</div><div><h4>'+t('0,5 × A + 0,5 × B','0.5 × A + 0.5 × B')+'</h4>'+eq('0 + '+n(value)+' × '+n(.5)+' / 2 = '+n(second))+p(t('błąd dopasowania + dodatek','fitting error + addition'))+'</div></div>'+p(value===0?t('Remis na historii. Te same trafienia nie określają reakcji na nową sytuację.','A tie on history. Identical hits do not determine the response to a new situation.'):t('Ridge preferuje niższą ocenę — z tych dwóch kandydatów wybiera więc drugi. To wybór według reguły dopasowania, jeszcze nie sprawdzian prognoz na nowych danych.','Ridge prefers the lower score, so it chooses the second of these two candidates. This is a choice under the fitting rule, not yet a test of predictions on new data.'));
 }
 if(key==='elastic'){
  const r=M.elasticSettingsToy(value),candidates=[...new Set([0,.6,r.beta])];
  return '<div class="lab-readout">λ = '+n(value)+' · '+t('próg L1 = ','L1 threshold = ')+n(r.l1)+' · β = <strong>'+n(r.beta,4)+'</strong></div>'+
   '<div class="lab-comparison">'+candidates.map((b,i)=>{const error=(.6-b)**2/2,l1=r.l1*Math.abs(b),l2=r.l2*b*b/2;return '<div'+(b===r.beta?' class="lab-winner"':'')+'><h4>'+[t('Wyłączone: β = 0','Off: β = 0'),t('Idealne trafienie: β = 0,6','Perfect fit: β = 0.6'),t('Najniższa ocena przy tej λ','Lowest score at this λ')][i]+(i<2&&b===r.beta?t(' — najniższa ocena',' — lowest score'):'')+'</h4>'+eq('β = '+n(b,4))+eq(n(error,5)+' + '+n(l1,5)+' + '+n(l2,5)+' = '+n(error+l1+l2,5))+p(t('punkty za pomyłkę + L1 + L2 = razem','error score + L1 + L2 = total'))+'</div>';}).join('')+'</div>'+
   p(r.beta===0?t('Próg ≥ 0,6: dokładne zero ma najniższą ocenę. Prognoza: 10; pomiar: 10,6.','Threshold ≥ 0.6: exact zero has the lowest score. Prediction: 10; observation: 10.6.'):t('Próg < 0,6: zostaje dodatni mnożnik. Dla pomiaru 10,6 prognoza wynosi ','Threshold < 0.6: a positive multiplier remains. For the observation of 10.6, the prediction is ')+n(r.prediction,4)+'.');
 }
 if(key==='huber'){
  const delta=D.parameters.huberDelta,r=M.huberPoint(value,delta);
  return '<div class="lab-readout">|r| = '+n(value)+' AAS '+(value<=delta?'≤':' >')+' δ = '+n(delta)+' AAS</div>'+chart([{color:'#756c5c',fn:x=>x*x/2},{color:'#21574e',fn:x=>M.huberPoint(x,delta).loss}],{xmax:12,ymax:72,xlabel:t('wielkość błędu |r| (AAS)','error magnitude |r| (AAS)'),ylabel:t('punkty błędu','error score'),marker:{x:value,y:r.loss},threshold:delta})+
   '<div class="lab-legend"><span>━ '+t('Szary: zwykły kwadrat / 2','Grey: ordinary square / 2')+'</span><strong>━ Huber</strong></div>'+eq(t('punkty za zwykły kwadrat: ','ordinary squared-error score: ')+n(value)+'² / 2 = '+n(r.squared))+eq('Huber: '+(value<=delta?n(value)+'² / 2':n(delta)+' × ('+n(value)+' − '+n(delta)+' / 2)')+' = '+n(r.loss))+eq(t('waga: ','weight: ')+(value<=delta?'1':n(delta)+' / '+n(value)+' = '+n(r.weight)))+
   p(value<=delta?t('Poniżej progu obie krzywe się pokrywają. Pomiar bierze udział z pełną wagą.','Below the threshold the two curves coincide. The observation receives full weight.'):t('Powyżej progu zielona krzywa nadal rośnie, ale już po prostej. Podwojenie dużego błędu nie mnoży jego punktów przez cztery. Jego punkty rosną dalej, tylko wolniej.','Above the threshold the green curve keeps rising, but in a straight line. Doubling a large error no longer quadruples its score. Its score keeps growing, only more slowly.'))+
   p(value<=delta?t('Do progu nacisk rośnie razem z błędem: wynosi ','Up to the threshold, pressure grows with the error: it is ')+n(r.pressure)+'.':t('Powyżej progu nacisk tej reszty zatrzymuje się na δ = ','Above the threshold, this residual’s pressure stops at δ = ')+n(delta)+t(', zamiast wynosić ', ', rather than ')+n(value)+t(' jak przy zwykłym kwadracie.',' as with ordinary squared loss.'));
 }
 const q=M.quantileToy(value,routineCount),scenario=routineCount===4?t('Raz na 5: najmniejszy koszt przy prognozie 30 AAS.','1 in 5: lowest cost at a prediction of 30 AAS.'):routineCount===19?t('Raz na 20: wszystkie prognozy od 10 do 30 mają ten sam koszt 19. Płaskie dno — nie jeden wybrany wynik.','1 in 20: every prediction from 10 to 30 has the same cost of 19. A flat bottom, not one unique answer.'):t('Raz na 21: najmniejszy koszt przy 10 AAS, mimo że maksimum nadal wynosi 30. Q95 nie jest maksimum.','1 in 21: lowest cost at 10 AAS, although the maximum is still 30. Q95 is not the maximum.');
 return '<div class="lab-readout">'+t('Przewidujesz ','You predict ')+n(value)+' AAS → '+t('łączny koszt ','total cost ')+'<strong>'+n(q.total)+'</strong></div>'+chart([{color:'#21574e',fn:x=>M.quantileToy(x,routineCount).total}],{xmax:40,ymax:M.quantileToy(0,routineCount).total*1.05,xlabel:t('przewidywana zmiana (AAS)','predicted change (AAS)'),ylabel:t('łączny koszt','total cost'),marker:{x:value,y:q.total}})+p(scenario)+
  '<div class="lab-costs">'+(routineCount===4?q.observations.map((y,i)=>'<div><span>'+t('Pomiar ','Observation ')+(i+1)+': '+y+' AAS</span><b>'+n(y>=value?.95:.05)+' × '+n(Math.abs(y-value))+' = '+n(q.costs[i])+'</b><small>'+t(value<y?'za nisko':value>y?'za wysoko':'trafiony',value<y?'too low':value>y?'too high':'exact')+'</small></div>').join(''):'<div><span>'+routineCount+' × 10 AAS</span><b>'+routineCount+' × '+n(q.costs[0])+' = '+n(routineCount*q.costs[0])+'</b></div><div><span>1 × 30 AAS</span><b>'+n(q.costs.at(-1))+'</b></div>')+'</div>';
}
function bindLab(key,lang,D){
 const input=document.getElementById('model-lab-slider'),output=document.getElementById('model-lab-result');
 const frequency=document.getElementById('q-frequency');
 const update=value=>{output.innerHTML=result(key,value,lang,D,frequency?+frequency.value:4);input.setAttribute('aria-valuetext',words(lang).n(value,4));};
 input.oninput=()=>{update(+input.value);if(key==='elastic'){const plain=document.getElementById('intuition-slider');plain.value=input.value;plain.setAttribute('aria-valuetext',words(lang).n(+input.value));document.getElementById('intuition-result').innerHTML=root.ModelIntuition.result(key,+input.value,lang);}};
 document.querySelectorAll('[data-lab-value]').forEach(b=>b.onclick=()=>{const value=+b.dataset.labValue;input.value=value;update(value);});
 if(frequency)frequency.onchange=()=>update(+input.value);
 const meanButton=document.querySelector('[data-q-mean]');if(meanButton)meanButton.onclick=()=>{const count=+frequency.value,value=(10*count+30)/(count+1);input.value=value;update(value);};
 update(+input.value);
}
function metricGuide(lang,metric){
 const {t}=words(lang),cut=metric==='p90'?90:metric==='p99'?99:100;
 const meaning=metric==='p90'?t('P90: wielkość, której nie przekracza około 90% zmian danego oczekiwania. Większe skoki są w pozostałych około 10%.','P90: a magnitude that roughly 90% of changes in this wait do not exceed. Larger jumps are in the remaining roughly 10%.'):metric==='p99'?t('P99: wielkość, której nie przekracza około 99% zmian danego oczekiwania. Przyglądamy się rzadkim, dużym skokom.','P99: a magnitude that roughly 99% of changes in this wait do not exceed. We are looking at rare, large jumps.'):t('MAX: największa zaobserwowana bezwzględna zmiana danego oczekiwania — nawet jeśli zdarzyła się tylko raz.','MAX: the largest observed absolute change in this wait, even if it happened only once.');
 return '<section class="percentile-guide"><h3>'+t('Jak duży skok bierzemy pod lupę?','How large a jump are we examining?')+'</h3>'+p(meaning)+'<details id="percentile-details"><summary>'+t('Pokaż P90, P99 i MAX na kolejce 101 zmian','Show P90, P99 and MAX in a queue of 101 changes')+'</summary>'+p(t('Najpierw policz zmianę między sąsiednimi pomiarami i odrzuć jej znak: −20 s i +20 s to skok tej samej wielkości. Dopiero kopię tych wielkości ustaw w kolejce od najmniejszej do największej.','First calculate each change between adjacent observations and remove its sign: −20 s and +20 s are equally large changes. Only then sort a copy of those magnitudes from smallest to largest.'))+
  '<div class="percentile-queue" role="img" aria-label="'+t('Ilustracja: 101 uporządkowanych wielkości, wybrano ','Illustration: 101 sorted magnitudes, selected ')+metric.toUpperCase()+'">'+Array.from({length:101},(_,i)=>'<i class="'+(i===cut?'selected':i<cut?'before':'')+'"></i>').join('')+'</div><p class="micro">'+t('Każda kreska = jeden wpis. Kolor pokazuje pozycję, nie wysokość wartości.','Each mark = one entry. Colour shows position, not value height.')+'</p>'+
  p(t('Wyobraź sobie 101 zmian: 0, 1, 2, …, 99 i na końcu jeden potwór 1 000 sekund. To wymyślona kolejka do nauki, nie nasze pomiary.','Imagine 101 changes: 0, 1, 2, …, 99 and one monster of 1,000 seconds at the end. This is an invented teaching queue, not our measurements.'))+
  '<dl class="metric-definitions"><div><dt>P90 = 90 s</dt><dd>'+t('Granica około 90% uporządkowanej listy; w tej miniaturze wpis nr 91. Około 10% zmian jest większych.','A boundary around 90% of the sorted list; entry 91 in this miniature. Roughly 10% of changes are larger.')+'</dd></div><div><dt>P99 = 99 s</dt><dd>'+t('Granica około 99%; tu wpis nr 100. Patrzymy znacznie bliżej skrajnych skoków.','A boundary around 99%; entry 100 here. We look much closer to the extreme jumps.')+'</dd></div><div><dt>MAX = 1 000 s</dt><dd>'+t('Największy zaobserwowany skok, choćby zdarzył się tylko raz. Nie największy możliwy skok w przyszłości.','The largest observed jump, even if it happened only once. Not the largest possible future jump.')+'</dd></div></dl>'+
  p(t('Jeden gość zamawiający sto piw nie mówi, ile zamawia zwykły stolik. Ale nie wolno udawać, że gościa nie było. Dlatego oglądamy kilka skal, zamiast wybierać jedną „prawdziwą”.','One guest ordering a hundred beers does not tell you what an ordinary table orders. But you cannot pretend the guest never arrived. That is why we inspect several scales instead of choosing one “true” measure.'))+
  p(t('P90/P99 wybierają rozmiar zmiany oczekiwania na wejściu. Q95 to osobny model: szacuje poziom zmiany AAS, którego nie powinno przekraczać około 95% wyników przy podobnych wejściach. AAS opisuje średnią liczbę aktywnych sesji w oknie; czas pojedynczego SQL wymaga innych danych.','P90/P99 select input wait-change magnitudes. Q95 is a separate model: it estimates an AAS-change level that roughly 95% of outcomes should not exceed for similar inputs. AAS describes average active sessions in a window; individual SQL time requires other data.'))+'</details></section>';
}
function rankingGuide(lang,model,metric){
 const {t}=words(lang),names={ridge:'Ridge',elastic:'Elastic Net',huber:'Huber',quantile:'Q95'};
 const descriptions={
 ridge:t('Ridge dopasowuje przeciętną zmianę AAS, ograniczając łączną wielkość mnożników.','Ridge fits the average AAS change while limiting overall multiplier size.'),
 elastic:t('Elastic Net dopasowuje zmianę AAS i może nadać części oczekiwań mnożnik zero.','Elastic Net fits AAS change and can give some waits a multiplier of zero.'),
 huber:t('Huber ogranicza wpływ dużych pomyłek prognozy na dopasowanie.','Huber limits the influence of large prediction errors on the fit.'),
 quantile:t('Q95 szacuje poziom zmiany AAS, którego nie powinno przekraczać około 95% wyników przy podobnych zmianach oczekiwań. W tej próbce jego obliczenia nie spełniły warunków zakończenia.','Q95 estimates an AAS-change level that roughly 95% of outcomes should not exceed for similar wait changes. Its calculation did not meet the stopping conditions in this sample.')
 };
 return '<section class="ranking-guide"><h3>'+t('Dwie decyzje, jedno pytanie','Two choices, one question')+'</h3>'+p(t('<strong>Model</strong> wybiera sposób dopasowania związku. <strong>P90 / P99 / MAX</strong> wybiera rozmiar zmiany każdego oczekiwania, dla którego obliczamy odpowiedź tego modelu.','<strong>Model</strong> selects how to fit the relationship. <strong>P90 / P99 / MAX</strong> selects each wait’s change magnitude at which we calculate that model’s response.'))+
 p('<strong>'+names[model]+':</strong> '+descriptions[model])+
 p(t('Słupek odpowiada: o ile zmieniłaby się prognoza, gdyby to jedno oczekiwanie wzrosło o wybrany rozmiar, a pozostałe się nie zmieniły? Większy dodatni wynik daje wcześniejszy trop do sprawdzenia.','Each bar asks: how far would the prediction move if this one wait rose by the chosen magnitude while the others stayed the same? A larger positive result gives an earlier lead to investigate.'))+
 '<button type="button" id="signal-model-explain" aria-haspopup="dialog" aria-controls="model-dialog">'+t('Wyjaśnij model ','Explain ')+names[model]+' 🍺</button>'+
 (model==='ridge'?'<details><summary>'+t('Czym Ridge × P99 różni się od Q95?','How does Ridge × P99 differ from Q95?')+'</summary>'+p(t('P99 wybiera duży skok oczekiwania na wejściu. Ridge nadal oblicza przesunięcie swojej prognozy przeciętnej zmiany AAS. Q95 dopasowuje inny wzór: pyta o wysoki poziom wyniku AAS przy danych wejściach. Duży skok wejścia i wysoki poziom wyniku to dwa różne pytania.','P99 selects a large input wait change. Ridge still calculates a shift in its prediction of average AAS change. Q95 fits a different formula: it asks about a high AAS-change outcome for the inputs. A large input jump and a high output level are two different questions.'))+'</details>':'')+'</section>';
}
function provenance(lang,D,P,fit,model,metric,top){
 const {t,n}=words(lang),j=top.j,i=D.focus,ss=M.sum(P.dx.map(r=>(r[j]-P.mean[j])**2)),pct=M.percentileTrace(P.dx.map(r=>Math.abs(r[j])),metric==='p90'?.9:metric==='p99'?.99:1),ridge=model==='ridge';
 const others=ridge?M.sum(fit.A[j].map((a,k)=>k===j?0:a*fit.beta[k])):0;
 const missing=D.missingCounts[j],bound=Math.min(P.n,2*missing);
 const missingText=missing===0?t('Ta kolumna nie ma wpisów zastąpionych zerem. Dopasowanie korzysta jednak również z innych kolumn, które mają braki.','This column has no zero-filled entries. The fit also uses other columns with missing data.'):
 t('Wpisy tej kolumny zastąpione zerem: ','Zero-filled entries in this column: ')+n(missing,0)+t('. Nie znamy ich pozycji. Każdy taki wpis może wpłynąć na najwyżej dwie sąsiednie różnice — przed nim i po nim. Górna granica to więc ','. Their positions are unknown. Each entry can affect at most two adjacent differences, one before and one after it. The upper bound is therefore ')+n(bound,0)+t(' z ',' of ')+n(P.n,0)+t(' różnic; faktycznej liczby nie ustalimy bez pozycji braków. Sztuczne skoki mogą zmieniać skalę, percentyle i mnożniki.',' differences; their actual number needs the missing-entry positions. Artificial jumps can change scaling, percentiles and multipliers.');
 return '<section class="formula-panel provenance">'+(model==='quantile'?'<p class="provenance-excluded">'+t('Q95: przykład rachunku na wyniku, który nie przeszedł kontroli zakończenia obliczeń. Nie używamy go do etykiet podsumowujących zgodność modeli.','Q95: arithmetic using a result that failed the stopping checks. It is not used for labels summarising agreement between models.')+'</p>':'')+'<span class="tag">'+t('SKĄD TA LICZBA? · OD MNOŻNIKA DO SŁUPKA','WHERE DOES THIS NUMBER COME FROM? · FROM MULTIPLIER TO BAR')+'</span><h3>'+esc(top.name)+'</h3>'+
 p(t('Mnożnik po przeliczeniu na sekundy × wybrana wielkość skoku = wynik słupka. Dla tego oczekiwania:','Multiplier converted to seconds × chosen jump magnitude = bar score. For this wait:'))+
 eq((top.raw<0?'max(0; '+n(top.raw,8)+')':n(top.raw,8))+' AAS/s × '+n(top.magnitude)+' s ≈ '+n(top.impact)+' AAS')+
 p(model==='quantile'?t('Tutaj wynik opisuje przesunięcie prognozowanego wysokiego poziomu (Q95) zmiany AAS.','Here the score describes a shift in the predicted high level (Q95) of AAS change.'):t('Tutaj wynik opisuje przesunięcie zmiany AAS przewidywanej przez wybrany model.','Here the score describes a shift in the AAS change predicted by the selected model.'))+
 p(missingText)+
 '<details class="provenance-steps"><summary>'+t('Rozwiń sześć kroków: skąd mnożnik i rozmiar skoku?','Expand six steps: where do the multiplier and jump size come from?')+'</summary>'+steps([
  [t('Źródło: sąsiednie odczyty → 1 338 zmian','Source: adjacent readings → 1,338 changes'),p(t('Z 1 339 wierszy danych kursu odejmujemy każdy poprzedni od następnego. Np. para 447 → 448 dla tego oczekiwania:','From the course’s 1,339 rows, subtract each previous row from the next. For example, pair 447 → 448 for this wait:'))+eq(n(D.x[i+1][j])+' − '+n(D.x[i][j])+' = '+n(P.dx[i][j])+' s')+p(t('To pojedynczy przykład wejścia. Końcowy słupek używa wszystkich par, nie tylko tego skoku.','This is one input example. The final bar uses all pairs, not just this jump.'))],
  [t('Skąd dzielnik ','Where the divisor ')+n(P.sd[j],6)+t(' s?',' s comes from'),p(t('To odchylenie standardowe tych 1 338 zmian. Średnia zmian wynosi ','It is the sample standard deviation of those 1,338 changes. The mean change is ')+n(P.mean[j],6)+' s. '+t('Można ją sprawdzić krócej: suma sąsiednich różnic to ostatni odczyt minus pierwszy.','A shortcut checks the mean: the sum of adjacent differences is the last reading minus the first.'))+eq('('+t('ostatni: ','last: ')+n(D.x.at(-1)[j])+' s − '+t('pierwszy: ','first: ')+n(D.x[0][j])+' s) / '+n(P.n,0)+' ≈ '+n(P.mean[j],6)+' s')+p(t('Od każdej zmiany odejmij tę średnią, podnieś różnicę do kwadratu i zsumuj. Podziel przez 1 337, potem wyciągnij pierwiastek:','Subtract this mean from each change, square each difference and add them up. Divide by 1,337, then take the square root:'))+eq('√('+n(ss,3)+' / '+n(P.n-1,0)+') ≈ '+n(P.sd[j],6)+' s')+p(t('Ta sama skala służy wcześniej do przeliczenia wejścia: z = (zmiana − średnia) / odchylenie.','The same scale is used earlier to transform the input: z = (change − mean) / standard deviation.'))],
  [t('Skąd mnożnik β = ','Where β = ')+n(top.beta,6)+t('?',' comes from'),p(ridge?t('Przeglądarka rozwiązała wspólnie cztery równania Ridge dla wszystkich par, przy λ = ','The browser jointly solved four Ridge equations over all pairs, with λ = ')+n(fit.lambda,4)+t('. Poniżej podstawiamy gotowe mnożniki do równania tej cechy, aby sprawdzić wynik:','. Below we put the fitted multipliers back into this predictor’s equation to check the result:'):t('To współczynnik z wyniku tego modelu zapisanego dla danych kursu do tych samych czterech kolumn. Nie przeliczamy go tym suwakiem ani równaniami Ridge.','This coefficient comes from this model’s saved fit to the same four columns. It is not refitted with this slider or with the Ridge equations.'))+(ridge?eq('β = ('+n(fit.rhs[j],6)+' − ('+n(others,6)+')) / '+n(fit.A[j][j],6)+' ≈ '+n(top.beta,6))+p(t('Pierwsza liczba: dla każdej z 1 338 par mnożymy przeskalowaną zmianę tego oczekiwania (symbol <i>z</i>) przez zmianę AAS po odjęciu średniej zmiany AAS. Następnie uśredniamy te iloczyny. Od niej odejmujemy łączny wkład pozostałych trzech współczynników w tym równaniu. Dzielnik to średnia z² + λ. Wartości wszystkich czterech mnożników muszą równocześnie spełniać cały układ.','For the first number, multiply each pair’s scaled wait change (symbol <i>z</i>) by its AAS change minus the mean AAS change. Then average these products over all 1,338 pairs. Subtract the other three coefficients’ combined contribution to this equation. The divisor is mean z² + λ. All four multipliers must satisfy the whole system simultaneously.'))+p(t('Średnia kwadratów przeskalowanej kolumny wynosi (N − 1) / N, bo przy obliczaniu jej odchylenia dzieliliśmy przez N − 1. Stąd dzielnik w tym równaniu:','The scaled column’s mean square is (N − 1) / N, because its standard deviation used N − 1 as the divisor. That gives this equation’s divisor:'))+eq(n(P.n-1,0)+' / '+n(P.n,0)+' + '+n(fit.lambda,4)+' ≈ '+n(fit.A[j][j],6))+p(t('Rozpiszmy odejmowany wkład pozostałych mnożników. Każda liczba stojąca przed β jest średnią iloczynów przeskalowanej kolumny tego oczekiwania i drugiego oczekiwania, dla tych samych par. To współczynniki w wierszu R','Expand the subtracted contribution of the other multipliers. Each number before β is the mean product of this wait’s scaled column and the other wait’s scaled column, across the same pairs. These are the entries in row R')+(j+1)+t(' układu:',' of the system:'))+fit.A[j].map((a,k)=>k===j?'':eq('β'+(k+1)+' ('+esc(D.features[k])+'): '+n(a,8)+' × '+n(fit.beta[k],8)+' ≈ '+n(a*fit.beta[k],8))).join('')+eq(t('Suma wkładów ≈ ','Combined contribution ≈ ')+n(others,6))+'<button type="button" id="show-beta-system">'+t('Pokaż pełny układ i eliminację Gaussa ↓','Show the full system and Gaussian elimination ↓')+'</button>':'')+p(t('β mówi, o ile AAS przesuwa się ','β says how far in AAS we shift ')+(model==='quantile'?t('przewidywany poziom Q95 zmiany AAS','the predicted Q95 level of AAS change'):t('przewidywana zmiana AAS','the predicted AAS change'))+t(', gdy to oczekiwanie rośnie o jedną jednostkę przeskalowanej wartości <i>z</i>, przy pozostałych oczekiwaniach stałych.',', when this wait increases by one unit of its scaled value <i>z</i>, with the other waits held fixed.'))],
  [t('Wróć ze skali z do sekund oczekiwania','Return from z units to wait seconds'),eq(n(top.beta,6)+' / '+n(P.sd[j],6)+' ≈ '+n(top.raw,8)+' AAS/s')+p(t('Jeden krok z to ','One z step is ')+n(P.sd[j],6)+t(' sekund zmiany. Dzielimy więc mnożnik przez tyle sekund. To współczynnik związku w modelu, nie przelicznik przyczynowy.',' seconds of change. Divide the multiplier by that many seconds. This is a fitted association, not a causal conversion rate.'))],
  [t('Skąd wielkość ','Where the ')+metric.toUpperCase()+t('?',' magnitude comes from'),metric==='max'?p(t('Bierzemy największą z 1 338 wartości |Δx|: ','Take the largest of the 1,338 |Δx| values: '))+eq(n(pct.value)+' s'):p(t('Sortujemy kopię 1 338 wartości |Δx|. Pozycje liczymy od 1; gdy wynik wypada między dwoma wpisami, bierzemy odpowiednią część odległości między nimi.','Sort a copy of the 1,338 |Δx| values. Positions start at 1; when the position falls between entries, take the corresponding fraction of the distance between them.'))+eq('1 + ('+n(P.n,0)+' − 1) × '+(metric==='p90'?n(.9):n(.99))+' = '+n(pct.position))+p(t('Pozycja ','Position ')+n(pct.lowerPosition,0)+': '+n(pct.lower)+' s; '+t('pozycja ','position ')+n(pct.upperPosition,0)+': '+n(pct.upper)+' s.')+eq(n(pct.lower)+' + '+n(pct.fraction)+' × ('+n(pct.upper)+' − '+n(pct.lower)+') ≈ '+n(pct.value)+' s')],
  [t('Dopiero teraz powstaje słupek','Only now do we calculate the bar'),eq(n(top.raw,8)+' × '+n(top.magnitude)+' ≈ '+n(top.impact)+' AAS')+p(t('Możesz też spojrzeć odwrotnie: rozmiar skoku / skala mówi, ile jednostek z ma ten skok.','Or look at it the other way round: jump size / scale tells you how many z units the jump spans.'))+eq(n(top.magnitude)+' / '+n(P.sd[j],3)+' ≈ '+n(top.magnitude/P.sd[j])+'; '+n(top.beta,3)+' × '+n(top.magnitude/P.sd[j])+' ≈ '+n(top.impact)+' AAS')+p(t('Mnożnik w AAS/s × wielkość zmiany w s. Odpowiada na pytanie: o ile AAS przesunie się '+(model==='quantile'?'szacowany poziom Q95 zmiany AAS':'przewidywana zmiana AAS')+' między sąsiednimi oknami, jeśli ta cecha wzrośnie o taką wielkość, a pozostałe pozostaną stałe? Pomaga wybrać kolejność pytań. Nie jest prognozą całego incydentu, zmierzonym udziałem w DB Time ani obietnicą odzyskania czasu. Izoluje jedną cechę; taki ruch przy pozostałych stałych nie musi występować w rzeczywistych pomiarach. Niedodatnie β otrzymują w tym rankingu wynik 0.','Multiplier in AAS/s × change magnitude in s. It answers: how far in AAS would '+(model==='quantile'?'the estimated Q95 level of AAS change':'the predicted AAS change')+' between adjacent windows move if this predictor increased by that amount and the others stayed fixed? It helps order investigative questions. It is not a whole-incident prediction, a measured share of DB Time or a promise of recoverable time. It isolates one predictor; such a change with all others fixed need not occur in actual observations. Non-positive β gets a ranking score of 0.'))+p(t('Więcej cyfr pozwala sprawdzić rachunek, nie obiecuje takiej dokładności pomiaru. Wyświetlane liczby są zaokrąglone; obliczenia korzystają z pełnej precyzji. Model analizuje łącznie cztery wybrane oczekiwania. Pozostałe źródła obciążenia nie są osobnymi wejściami tego dopasowania.','Extra digits let you reproduce the arithmetic; they do not imply that measurement accuracy. Displayed numbers are rounded; calculations use full precision. The model analyses four selected waits together. Other sources of load are not separate inputs in this fit.'))]
 ])+'</details></section>';
}
root.LearningPanels={lab,bindLab,result,metricGuide,provenance,rankingGuide};
})(typeof globalThis!=='undefined'?globalThis:this);
